/* Diner stories: branching choices, delayed consequences and the owner's growth.
   Every story is told by a seated guest in conversation. The telling ("tale") comes in beats: the guest
   says a little, the owner draws the next beat out ("asks"), and the choices come with the whole of it.
   The guest then answers what the owner actually did (the choice's "reply") and closes the night
   ("afterword"), and after the owner's closing reflection orders out of that same story ("order",
   with {dish} for the dish of the night). Stories with "arc" are chapters of a thread, told once, one a night, in the order
   written here ("after" names the chapter that must come first; "act" is the part of the whole they
   belong to). Stories without "arc" are single nights that rotate on the first night and once every
   chapter is told.
   Each choice and closing reflection has a "trait" (listen / act / keep): the owner grows by what
   they choose ("growth"), a choice with "needs" opens only to an owner grown enough, and "echo" adds
   sentences that earlier choices ("if": "story:choice") or the owner's leading trait ("lead") have
   earned ("beat" says in which beat of the telling). "whispers" is a hidden episode: fragments a guest lets slip only deep in an ordinary
   conversation, a few things the owner notices alone, and one rare night; no screen lists them.
   "lullaby" is a second hidden episode: six lines of one song, each hummed by a different
   guest after ordering; the owner who has heard them all may one night be asked to put them in order.
   "source" names the public-domain work whose
   structure a thread borrows. All people, places, events and sentences are original. */
